{
  "reply": "Хотите изменить только главный перевод (*primaryGloss*) и короткий глоссарий (*shortGloss*), оставив первый научный смысл как есть?",
  "followUps": [
    "Yes, update the main glosses",
    "How does the usage differ?",
    "Give me one more example"
  ],
  "proposal": {
    "summary": "Updates the primary gloss and short gloss to use «бездонный».",
    "ops": [
      {
        "op": "set",
        "target": "lexeme",
        "field": "primaryGloss",
        "value": "бездонный"
      },
      {
        "op": "set",
        "target": "lexeme",
        "field": "shortGloss",
        "value": "бездонный; глубоководный"
      }
    ]
  }
}
